SELECT event_cohort, page_view_count, duration_sec_range FROM (SELECT CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END AS event_cohort, SUM(CASE WHEN event_type = 'page_view' THEN 1 ELSE 0 END) AS page_view_count, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range FROM web_events GROUP BY CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END) AS s WHERE page_view_count > 49 ORDER BY page_view_count DESC, event_cohort LIMIT 5
